  "check_code": "import hashlib
import json
import re
import sqlite3
from pathlib import Path


CASE_ID = "case_2025_0912_0476"
BASELINE_COMMUNICATION_IDS = {
    "comm_2025_0913_0081",
    "comm_2025_0917_0144",
    "comm_2025_0926_0229",
    "comm_2025_0926_0241",
}
EOB_ISSUED_AT = "2025-09-26T16:18:00Z"

CRM_DIGESTS = {
    "agency_clients": (70, "480539d2715a808e62e524f1791686ead0a1d4ede687db4281113631796e343a"),
    "claim_cases": (83, "9b72dfcdae1e85eb3b9fb25f00f6a9c6e0c44ffcf354a21f91f0d27cc9597f7c"),
    "case_milestones": (253, "0489942ca40b97377c98f83bc450132481f18c89180ca8c929586969b727abd5"),
