    "target_historical_communications": (4, "092ea055c4bdb52909339c3d284d39c4d6ef6fa962f25f0d5c72af81b833b2ff"),
}

DOCUMENT_DB_DIGESTS = {
    "claim_packets": (63, "18fef5436f53f242b8fed0f1f1908c8cae48e58b771763484699b90b07b4998d"),
