    "evidence_links": (156, "c65aefc0ce3bdb40f4e919c474a67db33645eee5a58ae9bca0e31b990661662d"),
}

WORKSPACE_HASHES = {
    "01_Source_Extracts/Juniper_Claim_Document_Index.csv": "40391604c4c7957ab41c3ab6670f581cf8645254137e22687dcb5df50f2c8536",
    "01_Source_Extracts/Juniper_Emergency_Surgery_Invoice_Line_Items.csv": "f76981f7fed9d08347e3bdd43f04205d8aba2f812dacaa8484260a81ad12ee6a",
