def _system_db(ws, system_name):
    return Path(ws).resolve().parent / "system" / system_name / "state.db"


def _fetch_rows(db_path, sql, params=()):
    connection = sqlite3.connect(str(db_path))
    connection.row_factory = sqlite3.Row
    try:
        return [dict(row) for row in connection.execute(sql, params).fetchall()]
    finally:
        connection.close()


def _new_target_rows(ws):
    rows = _fetch_rows(
        _system_db(ws, "dvm_agency_claims_crm"),
        "SELECT * FROM case_communications WHERE case_id = ? ORDER BY communication_id",
        (CASE_ID,),
    )
    return [row for row in rows if row["communication_id"] not in BASELINE_COMMUNICATION_IDS]


def _normalized_text(value):
    return re.sub(r"[^a-z0-9]+", " ", (value or "").lower()).strip()


def _has_any(text, alternatives):
    return any(re.search(pattern, text) for pattern in alternatives)


def _query_digest(db_path, sql, params=()):
    connection = sqlite3.connect(str(db_path))
    try:
        rows = connection.execute(sql, params).fetchall()
    finally:
        connection.close()
    payload = json.dumps(rows, ensure_ascii=False, separators=(",", ":"), default=str).encode("utf-8")
    return len(rows), hashlib.sha256(payload).hexdigest()


def check_communication_identity(ws):
    new_rows = _new_target_rows(ws)
    if len(new_rows) != 1:
        return {"score": 0, "detail": f"Expected exactly one new communication on Juniper's case; found {len(new_rows)}."}
    row = new_rows[0]
    expected = {
        "communication_type": "status_update",
        "recipient": "emily.carter@example.com",
        "message_status": "delivered",
        "source_system": "dvm_agency_claims_crm",
    }
    mismatches = [key for key, value in expected.items() if _normalized_text(row.get(key)) != _normalized_text(value)]
    if mismatches:
        return {"score": 0, "detail": "New communication has incorrect " + ", ".join(mismatches) + "."}
    if not row.get("subject", "").strip() or not row.get("body", "").strip():
        return {"score": 0, "detail": "New communication subject and body must both be nonblank."}
    if row.get("sent_at", "") < EOB_ISSUED_AT:
        return {"score": 0, "detail": "The status update predates the existing EOB instead of being post-review follow-up."}
    return {"score": 1, "detail": "Exactly one delivered status update was added for Emily Carter after EOB issuance."}


def check_communication_content(ws):
    new_rows = _new_target_rows(ws)
    if len(new_rows) != 1:
        return {"score": 0, "detail": "There is not exactly one new target communication to evaluate."}
    text = _normalized_text(new_rows[0].get("subject", "") + " " + new_rows[0].get("body", ""))
    claim_reference = "vpi ca 250912 0476" in text or "claim vpi ca 250912 0476" in text
    supplemental_record = _has_any(text, [r"supplement(al|ary)", r"radiolog", r"imaging addendum", r"late medical record"])
    review_complete = "review" in text and _has_any(text, [r"\bcomplete\b", r"\bcompleted\b", r"\bverified\b", r"\bconcluded\b", r"\bfinished\b"])
    approved = _has_any(text, [r"\bapproved\b", r"\badjudicated\b"])
    existing_eob = _has_any(text, [r"existing (eob|explanation of benefits)", r"eob (already |previously )?(issued|available|remains)", r"explanation of benefits (already |previously )?(issued|available|remains)", r"approved eob workflow"])
    new_eob_language = _has_any(text, [r"new (eob|explanation of benefits)", r"replacement (eob|explanation of benefits)", r"another (eob|explanation of benefits)"])
    new_eob_negated = _has_any(text, [r"no (new|replacement|another) (eob|explanation of benefits)", r"not (issuing|issue|creating|create|sending|send) (a )?(new|replacement|another) (eob|explanation of benefits)"])
    checks = {
        "claim reference": claim_reference,
        "supplemental medical-record context": supplemental_record,
        "completed or verified review": review_complete,
        "approved/adjudicated status": approved,
        "existing EOB context": existing_eob,
        "no affirmative new-EOB wording": not new_eob_language or new_eob_negated,
    }
    failed = [label for label, passed in checks.items() if not passed]
    if failed:
        return {"score": 0, "detail": "Communication content is missing or conflicts with: " + ", ".join(failed) + "."}
    return {"score": 1, "detail": "Communication identifies the claim and accurately explains completed supplemental review within the existing approved EOB workflow."}


def check_crm_history_unchanged(ws):
    db_path = _system_db(ws, "dvm_agency_claims_crm")
    queries = {
        "agency_clients": "SELECT * FROM agency_clients ORDER BY 1",
        "claim_cases": "SELECT * FROM claim_cases ORDER BY 1",
        "case_milestones": "SELECT * FROM case_milestones ORDER BY 1",
        "non_target_communications": "SELECT * FROM case_communications WHERE case_id <> 'case_2025_0912_0476' ORDER BY communication_id",
    }
    changed = []
    for label, sql in queries.items():
        if _query_digest(db_path, sql) != CRM_DIGESTS[label]:
            changed.append(label)
    target_rows = _fetch_rows(db_path, "SELECT * FROM case_communications WHERE case_id = ?", (CASE_ID,))
    target_ids = {row["communication_id"] for row in target_rows}
    if not BASELINE_COMMUNICATION_IDS.issubset(target_ids):
        changed.append("historical target communications")
    placeholders = ",".join("?" for _ in BASELINE_COMMUNICATION_IDS)
    historical_digest = _query_digest(
        db_path,
        f"SELECT * FROM case_communications WHERE communication_id IN ({placeholders}) ORDER BY communication_id",
        tuple(sorted(BASELINE_COMMUNICATION_IDS)),
    )
    if historical_digest != CRM_DIGESTS["target_historical_communications"]:
        changed.append("historical target communication contents")
    if len(target_rows) != len(BASELINE_COMMUNICATION_IDS) + 1:
        changed.append("target communication count")
    if changed:
        return {"score": 0, "detail": "CRM history changed outside the one permitted insert: " + ", ".join(changed) + "."}
    return {"score": 1, "detail": "CRM claim history and unrelated records are unchanged apart from one new target communication."}


def check_source_evidence_unchanged(ws):
    db_path = _system_db(ws, "nationwide_claim_documents")
    changed = []
    for table, expected in DOCUMENT_DB_DIGESTS.items():
        if _query_digest(db_path, f"SELECT * FROM {table} ORDER BY 1") != expected:
            changed.append(f"Nationwide Claim Documents:{table}")
    ws_path = Path(ws)
    for relative_path, expected_hash in WORKSPACE_HASHES.items():
        path = ws_path / relative_path
        actual_hash = hashlib.sha256(path.read_bytes()).hexdigest() if path.is_file() else None
        if actual_hash != expected_hash:
            changed.append(relative_path)
    if changed:
        return {"score": 0, "detail": "Source evidence was modified: " + ", ".join(changed[:6]) + ("..." if len(changed) > 6 else "")}
    return {"score": 1, "detail": "Nationwide Claim Documents and all pre-existing workspace files are unchanged."}
